sys_script.script:
(function validateStateTransition(current, previous) {
    var newState = current.getValue('state');
    var oldState = previous.getValue('state');

    if (newState === oldState) return;

    // Only branch_manager can approve or reject
    if ((newState === 'approved' || newState === 'rejected') && !gs.hasRole('x_2220006_bankin_0.branch_manager') && !gs.hasRole('admin')) {
        gs.addErrorMessage('Only a Branch Manager can approve or reject requests');
        current.setValue('state', oldState);
    }

    // Only branch_officer or branch_manager can set to completed
    if (newState === 'completed' && !gs.hasRole('x_2220006_bankin_0.branch_officer') && !gs.hasRole('x_2220006_bankin_0.branch_manager') && !gs.hasRole('admin')) {
        gs.addErrorMessage('Only Branch Officers or Managers can complete requests');
        current.setValue('state', oldState);
    }

    // Prevent customers from changing state at all
    if (gs.hasRole('x_2220006_bankin_0.banking_customer') && !gs.hasRole('x_2220006_bankin_0.branch_officer') && !gs.hasRole('x_2220006_bankin_0.branch_manager') && !gs.hasRole('admin')) {
        if (newState !== oldState) {
            gs.addErrorMessage('You do not have permission to change the request state');
            current.setValue('state', oldState);
        }
    }
})(current, previous);
